
.section {
  margin-top: 8px;
}

.section-title {
  color: var(--c-text-muted);
  font-size: 12px;
  letter-spacing: 2px;
  margin-right: 10px;
}

.grid {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 6px;
}

.facility {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  font-size: 12px;
  color: var(--c-text-muted);
  border: 1px solid var(--c-border-soft);
  border-radius: 4px;
  padding: 1px 9px;
  opacity: 0.55;
}

.facility.built {
  color: var(--c-text);
  border-color: var(--c-border);
  opacity: 1;
}

.facility.built .fac-level {
  color: var(--c-accent-strong);
  font-weight: 600;
}
