
.xzj-panel {
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
  background-color: var(--c-surface);
  color: var(--c-text);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 12px 16px;
  font-family: var(--font-xian);
  font-size: 13px;
  line-height: 1.8;
}

.xzj-head {
  display: flex;
  align-items: baseline;
  gap: 12px;
  border-bottom: 1px solid var(--c-border-soft);
  padding-bottom: 8px;
  margin-bottom: 8px;
}

.xzj-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--c-accent);
  letter-spacing: 4px;
}

.xzj-stage {
  font-size: 12px;
  border: 1px solid var(--c-border);
  border-radius: 10px;
  padding: 1px 12px;
  line-height: 1.6;
}
