
.section {
  margin-top: 8px;
}

.section-title {
  color: var(--c-text-muted);
  font-size: 12px;
  letter-spacing: 2px;
  margin-right: 10px;
}

.list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 4px;
}

.task {
  font-size: 12px;
  border: 1px solid var(--c-border-soft);
  border-radius: 4px;
  padding: 4px 10px;
  background-color: var(--c-surface-raised);
}

.t-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
}

.t-name {
  color: var(--c-text-strong);
  font-weight: 600;
}

.t-reward {
  color: var(--c-accent);
  white-space: nowrap;
}

.t-desc {
  color: var(--c-text);
}

.t-goal {
  color: var(--c-text-muted);
}
