
.sect-stats {
  display: flex;
  gap: 24px;
  align-items: center;
  margin-top: 8px;
}

.stat-block .label {
  color: var(--c-text-muted);
  margin-right: 6px;
}

.stat-block .value {
  color: var(--c-text-strong);
  font-weight: 700;
}

.fame {
  flex: 1;
  min-width: 220px;
}

.fame .stat-head {
  display: flex;
  justify-content: space-between;
}

.bar {
  height: 6px;
  background-color: var(--c-surface-raised);
  border: 1px solid var(--c-border-soft);
  border-radius: 3px;
  overflow: hidden;
  margin-top: 3px;
}

.bar-fill {
  height: 100%;
  background-color: var(--c-accent);
  border-radius: 3px;
  transition: width 0.5s ease;
}

.bar-hint {
  font-size: 12px;
  color: var(--c-text-muted);
  margin-top: 2px;
}
