
.section {
  margin-top: 8px;
}

.section-title {
  color: var(--c-text-muted);
  font-size: 12px;
  letter-spacing: 2px;
  margin-right: 10px;
}

.chips {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  font-size: 12px;
  color: var(--c-text);
  border: 1px solid var(--c-border);
  border-radius: 4px;
  padding: 1px 9px;
}

.chip-name {
  color: var(--c-text-muted);
}

.chip-count {
  color: var(--c-text-strong);
  font-weight: 600;
}

.empty {
  font-size: 12px;
  color: var(--c-text-muted);
}
