
.section {
  margin-top: 8px;
}

.section-title {
  color: var(--c-text-muted);
  font-size: 12px;
  letter-spacing: 2px;
  margin-right: 10px;
}

.list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.disciple {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  font-size: 12px;
  border: 1px solid var(--c-border);
  border-radius: 4px;
  padding: 2px 10px;
}

.d-name {
  color: var(--c-text-strong);
  font-weight: 600;
}

.d-realm {
  color: var(--c-accent);
}

.d-state {
  color: var(--c-text-muted);
}
